#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long q;
    cin >> q;
    vector<vector<long long>> queries(q, vector<long long>(2));
    for (int i = 0; i < q; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> queries[i][j];
        }
    }

    for (const vector<long long>& query : queries) {
        int e = (int)query[0];
        long long f = query[1];
        vector<long long> reach(e + 1, 0);
        long long t = 0;
        while (reach[e] < f) {
            t++;
            for (int j = e; j >= 1; j--) reach[j] = min(f, reach[j - 1] + reach[j] + 1);
        }
        cout << t << "\n";
    }

    return 0;
}

