import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long q = Long.parseLong(next());
        long[][] queries = new long[(int) q][2];
        for (int i = 0; i < queries.length; i++) {
            for (int j = 0; j < queries[i].length; j++) {
                queries[i][j] = Long.parseLong(next());
            }
        }

        StringBuilder out = new StringBuilder();
        for (int index = 0; index < q; index++) {
            int e = (int) queries[index][0];
            long f = queries[index][1];
            long[] reach = new long[e + 1];
            long t = 0;
            while (reach[e] < f) {
                t++;
                for (int j = e; j >= 1; j--) reach[j] = Math.min(f, reach[j - 1] + reach[j] + 1);
            }
            out.append(t).append("\n");
        }
        System.out.print(out);
    }
}
